import React, { useState } from 'react';
import { formatLabel } from './util';

export function Counter({ initial }) {
  const [count, setCount] = useState(initial);
  return (
    <div className="counter">
      <h1>It's been {count} clicks</h1>
      <button onClick={() => setCount(count + 1)}>
        Click "me" / now
      </button>
      <ul>
        {items.map((item) => (
          <li key={item.id}>{formatLabel(item)}</li>
        ))}
      </ul>
    </div>
  );
}

export default Counter;

import { useEffect, useState } from 'react';
import styles from './styles.css' with { type: 'css' };

export const UserCard = ({ id }) => {
  const [user, setUser] = useState(null);
  useEffect(() => {
    fetch(`/api/users/${id}`).then((r) => r.json()).then(setUser);
  }, [id]);
  if (!user) return <div data-state="loading">Loading…</div>;
  return (
    <section className={styles.card}>
      {/* 头部 */}
      <h2>{user.name}</h2>
      {user.admin && <Badge text="admin's" />}
    </section>
  );
};

import React from 'react';
import { validate } from './validate';

export default function LoginForm() {
  const [email, setEmail] = React.useState('');
  const onSubmit = (e) => {
    e.preventDefault();
    if (!validate(email)) return;
  };
  return (
    <form onSubmit={onSubmit}>
      <label htmlFor="email">
        Don't worry, we'll never share it.
      </label>
      <input
        id="email"
        type="email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        placeholder="you@example.com"
      />
      <button type="submit">Sign in</button>
    </form>
  );
}
